select u.id, u.student_no, u.real_name, c.class_name, u.major, c.grade from sys_user u left join sys_user_class uc on uc.user_id = u.id and uc.relation_type = 1 left join sys_class c on uc.class_id = c.id WHERE u.user_type = 1 AND u.status = 1
AND uc.class_id = #{classId}
AND uc.class_id IN #{cid}
AND ${ew.sqlSegment}
